baseCss:
.aha-gallery{
  container:aha-gallery / inline-size;
  --aha-gallery-dot:var(--aha-vivid-pink-30);
  --aha-gallery-dot-hover:var(--aha-vivid-pink-dark);
  --aha-gallery-dot-current:var(--aha-color-primary);
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-gallery *{box-sizing:border-box}
.aha-gallery--accent{box-shadow:inset 0 0 0 100vmax var(--aha-bg-accent)}
:where(.aha-gallery) :is(h2,h3,p,ul,ol,figure){margin:0;padding:0}
:where(.aha-gallery) :is(ul,ol){list-style:none}
.aha-gallery__inner{--aha-web-gutter:var(--aha-space-64);max-width:1280px;margin:0 auto;padding:var(--aha-space-96) var(--aha-web-gutter)}
.aha-gallery__header{max-width:720px;margin:0 auto var(--aha-space-64);text-align:center}
.aha-gallery__eyebrow{
  margin:0 0 var(--aha-space-16);
  font-size:var(--aha-size-sm);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-subheadings);
  text-transform:uppercase;
  color:var(--aha-color-primary);
}
.aha-gallery__title{
  margin:0 0 var(--aha-space-20);
  font-size:var(--aha-size-h2);
  line-height:var(--aha-line-height-heading);
  font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-text-default);
}
.aha-gallery__lead{
  max-width:44ch;
  margin-inline:auto;
  font-size:clamp(var(--aha-size-l),1.4vw,var(--aha-size-xl));
  line-height:var(--aha-line-height-body);
  color:var(--aha-text-secondary);
}
.aha-gallery__image{display:block;width:100%;height:100%;object-fit:cover;border-radius:var(--aha-radius-marketing);background:var(--aha-bg-container-secondary)}
.aha-gallery__caption{margin-top:var(--aha-space-12);font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-gallery__cta{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--aha-space-12);margin-top:var(--aha-space-48)}
.aha-gallery__controls{display:flex;align-items:center;justify-content:center;gap:var(--aha-space-16);margin-top:var(--aha-space-24)}
.aha-gallery__dots{display:flex;justify-content:center;gap:var(--aha-space-4)}
.aha-gallery__dot{display:inline-flex;align-items:center;justify-content:center;min-width:var(--aha-space-24);height:var(--aha-space-24);padding:0 var(--aha-space-2);border:0;background:none;cursor:pointer}
.aha-gallery__dot[hidden]{display:none}
.aha-gallery__dot::before{content:"";display:block;width:var(--aha-space-16);height:var(--aha-space-4);border-radius:var(--aha-radius-pill);background:var(--aha-gallery-dot);transition:width var(--aha-motion-mid) var(--aha-ease-in-out),background-color var(--aha-motion-mid) var(--aha-ease-in-out)}
.aha-gallery__dot:hover::before{background:var(--aha-gallery-dot-hover)}
.aha-gallery__dot[aria-current="true"]::before{width:var(--aha-space-28);background:var(--aha-gallery-dot-current)}
.aha-gallery__dot:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:0;border-radius:var(--aha-radius-xs)}
@media (prefers-reduced-motion:reduce){
  .aha-gallery__dot::before{transition:none}
}
@container aha-gallery (max-width:991px){
  .aha-gallery__title{font-size:var(--aha-size-h3)}
}
@container aha-gallery (max-width:767px){
  .aha-gallery__inner{--aha-web-gutter:var(--aha-space-24);padding:var(--aha-space-48) var(--aha-web-gutter)}
  .aha-gallery__header{margin-bottom:var(--aha-space-48)}
}
@container aha-gallery (max-width:479px){
  .aha-gallery__inner{--aha-web-gutter:var(--aha-space-16);padding:var(--aha-space-32) var(--aha-web-gutter)}
  .aha-gallery__header{margin-bottom:var(--aha-space-32)}
  .aha-gallery__title{font-size:var(--aha-size-h4)}
  .aha-gallery__cta{margin-top:var(--aha-space-32)}
}
.aha-gallery__visually-hidden{
  position:absolute;width:1px;height:1px;margin:-1px;padding:0;
  overflow:hidden;clip-path:inset(50%);white-space:nowrap;
}

layouts.css:
.aha-gallery__bento{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));grid-template-rows:repeat(2,minmax(0,1fr));grid-template-areas:"large large first second" "large large third fourth";gap:var(--aha-space-16);aspect-ratio:2 / 1}
.aha-gallery__bento>:first-child{grid-area:large}
@container aha-gallery (max-width:767px){
  .aha-gallery__bento{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(4,minmax(0,1fr));grid-template-areas:"large large" "large large" "first second" "third fourth";aspect-ratio:1 / 2}
}
@container aha-gallery (max-width:479px){
  .aha-gallery__bento{gap:var(--aha-space-8)}
}

.aha-gallery__carousel{min-width:0}
.aha-gallery__track{/* ds-lint-allow: overflow-x-scroll (the photo row scrolls sideways by design, snapping photo by photo) */display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 2 * var(--aha-space-24)) / 3);gap:var(--aha-space-24);position:relative;overflow-x:auto;overscroll-behavior-x:contain;scroll-snap-type:x mandatory;scroll-behavior:smooth;scrollbar-width:none}
.aha-gallery__track::-webkit-scrollbar{display:none}
.aha-gallery__track:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);border-radius:var(--aha-radius-xs)}
.aha-gallery__slide{scroll-snap-align:start;min-width:0}
.aha-gallery__slide .aha-gallery__image{aspect-ratio:4 / 3;height:auto}
@media (prefers-reduced-motion:reduce){
  .aha-gallery__track{scroll-behavior:auto}
}
:where([data-aha-motion="off"]) .aha-gallery__track{scroll-behavior:auto}
@container aha-gallery (max-width:767px){
  .aha-gallery__track{grid-auto-columns:calc((100% - var(--aha-space-16)) / 1.6);gap:var(--aha-space-16)}
}
@container aha-gallery (max-width:479px){
  .aha-gallery__track{grid-auto-columns:85%;gap:var(--aha-space-12)}
}

.aha-gallery__stack{display:flex;flex-direction:column;gap:var(--aha-space-32)}
.aha-gallery__stack-card{position:sticky;top:var(--aha-space-32);display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:var(--aha-space-48);align-items:center;padding:var(--aha-space-32);border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-marketing);background:var(--aha-white)}
.aha-gallery__stack-card:nth-child(2){top:calc(var(--aha-space-32) + var(--aha-space-16))}
.aha-gallery__stack-card:nth-child(3){top:calc(var(--aha-space-32) + 2 * var(--aha-space-16))}
.aha-gallery__stack-card:nth-child(4){top:calc(var(--aha-space-32) + 3 * var(--aha-space-16))}
.aha-gallery__stack-card:nth-child(5){top:calc(var(--aha-space-32) + 4 * var(--aha-space-16))}
.aha-gallery__stack-card .aha-gallery__image{aspect-ratio:16 / 9;height:auto;border-radius:var(--aha-radius-lg)}
.aha-gallery__stack-text{display:flex;flex-direction:column;gap:var(--aha-space-12)}
.aha-gallery__stack-step{font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;color:var(--aha-color-primary)}
.aha-gallery__stack-title{font-size:var(--aha-size-h4);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-gallery__stack-description{font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
@container aha-gallery (max-width:767px){
  .aha-gallery__stack-card{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-20);padding:var(--aha-space-24)}
}
@container aha-gallery (max-width:479px){
  .aha-gallery__stack{gap:var(--aha-space-16)}
  .aha-gallery__stack-card{padding:var(--aha-space-16)}
  .aha-gallery__stack-title{font-size:var(--aha-size-h5)}
}

.aha-gallery__tabs{display:flex;flex-direction:column;gap:var(--aha-space-24)}
.aha-gallery__tablist{/* ds-lint-allow: overflow-x-scroll (tab row scrolls sideways on a phone, by design) */display:flex;gap:var(--aha-space-8);overflow-x:auto;scrollbar-width:none;border-bottom:1px solid var(--aha-border-default)}
.aha-gallery__tab{
  display:inline-flex;align-items:center;flex:none;
  padding:var(--aha-space-12) var(--aha-space-16);
  border:0;border-bottom:var(--aha-space-2) solid transparent;margin-bottom:-1px;
  background:none;font-family:inherit;font-size:var(--aha-size-l);font-weight:var(--aha-weight-semibold);
  color:var(--aha-text-secondary);cursor:pointer;
  transition:border-color var(--aha-motion-mid) var(--aha-ease-in-out),color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-gallery__tab:first-child{margin-left:auto}
.aha-gallery__tab:last-child{margin-right:auto}
.aha-gallery__tab:not([aria-selected="true"]):hover{border-bottom-color:var(--aha-border-hover);color:var(--aha-text-default)}
.aha-gallery__tab[aria-selected="true"]{border-bottom-color:var(--aha-color-primary);color:var(--aha-text-default)}
.aha-gallery__tab:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:calc(-1 * var(--aha-space-2));border-radius:var(--aha-radius-xs)}
.aha-gallery__panels{display:grid}
.aha-gallery__panel{grid-area:1 / 1;opacity:0;visibility:hidden;transition:opacity var(--aha-motion-viz-enter) var(--aha-ease-in-out),visibility 0s linear var(--aha-motion-viz-enter)}
.aha-gallery__panel[data-current]{opacity:1;visibility:visible;transition:opacity var(--aha-motion-viz-enter) var(--aha-ease-in-out)}
.aha-gallery__panel .aha-gallery__image{aspect-ratio:16 / 9;height:auto}
@media (prefers-reduced-motion:reduce){
  .aha-gallery__tab,.aha-gallery__panel,.aha-gallery__panel[data-current]{transition:none}
}
:where([data-aha-motion="off"]) :is(.aha-gallery__panel,.aha-gallery__panel[data-current]){transition:none}
